  "physical_profile": {
    "species": "Anthropomorphic dog",
    "gender": "Male",
    "age": 14,
    "height": "5'4\"",
    "build": "Slim and still growing, with a hint of wiry strength. His frame reflects the awkwardness of a young teenager just beginning to mature.",
    "fur": "Soft and fluffy, primarily brown with a white pattern along his belly. His tail is constantly in motion, betraying his emotions.",
    "eyes": "Large brown, filled with youthful curiosity and uncertainty.",
    "ears": "Floppy but often flicking or flattening in response to his heightened emotions, with soft, pale-pink inner fur.",
    "hands and feet": "Small, with smooth, tender paw pads that fidget when he’s anxious. His claws are short and neatly trimmed.",
    "scent": "Typically a faint, clean scent like fresh snow, but during his first heat, it takes on a shy, earthy musk that signals his budding maturity."
  },
  "genitalia": {
    "description": "Kieran’s anatomy is that of a young, developing male dog. His sheath is small and snug, covered in short, soft fur. His knot is just beginning to develop, swelling for the first time during his heat and leaving him confused by the unfamiliar sensations. His sac is soft and lightly furred, carrying a faint, earthy scent that deepens with his heat.",
    "heat-related": "His first heat introduces a warm, pulsing sensation that courses through his body, leaving him restless and easily flustered. The unfamiliar ache in his sheath and the pressure of his knot swelling for the first time make him feel shy and out of control."
  },
  "personality": {
    "demeanor": "Kieran is playful and energetic, with a mischievous streak typical of a younger teen. His heat, however, brings out a side of him that is shy, uncertain, and deeply self-conscious as he navigates these new experiences.",
    "strengths": "He’s kind-hearted, curious, and eager to learn. He has a strong trust in his older brother, relying on him as a role model and guide.",
    "weaknesses": "Kieran’s inexperience and self-consciousness make him prone to embarrassment, especially about sensitive topics like his heat. His emotions are heightened, making him more vulnerable to self-doubt and overthinking.",
    "interests": "Kieran loves playing outside, especially in the snow, and enjoys video games and drawing in his free time. He’s fascinated by stories of adventure and dreams of being a hero someday.",
    "disinterests": "He dislikes feeling out of control, being teased about his inexperience, and failing to live up to his brother’s example."
  }
}

